int mpg123_seek_point(uchar *TOC,int file_bytes,float percent)

{
  float percent_local;
  int file_bytes_local;
  uchar *TOC_local;
  int a;
  float fb;
  float fa;
  float fx;
  int seekpoint;

  percent_local = percent;
  if (percent < 0.0) {
    percent_local = 0.0;
  }
  if (100.0 < percent_local) {
    percent_local = 100.0;
  }
  a = (int)percent_local;
  if (99 < a) {
    a = 99;
  }
  if (a < 99) {
    fb = (float)TOC[(long)a + 1];
  }
  else {
    fb = 256.0;
  }
  return (int)((float)file_bytes *
              ((percent_local - (float)a) * (fb - (float)TOC[a]) + (float)TOC[a]) * 0.00390625);
}
